def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder and not postorder:
        return ""
    # Map each value to its index in inorder for O(1) lookups
    index_map = {ch: i for i, ch in enumerate(inorder)}

    def build(i_start: int, i_end: int, p_start: int, p_end: int) -> str:
        if i_start > i_end or p_start > p_end:
            return ""
        root = postorder[p_end]
        root_idx = index_map.get(root)
        if root_idx is None:
            # Invalid input; root not in inorder
            return ""
        left_size = root_idx - i_start
        left = build(i_start, root_idx - 1, p_start, p_start + left_size - 1)
        right = build(root_idx + 1, i_end, p_start + left_size, p_end - 1)
        return root + left + right

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

