def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
        T (int): The total time available for picking herbs.
        M (int): The number of different herbs in the cave.
        herbs (list): A list of tuples, where each tuple contains two integers
                      representing the time required to pick the herb and the herb's value.

    Returns:
        int: The maximum total value of herbs that can be picked within the time limit.

    Raises:
        TypeError: If T, M, or herbs has an inappropriate type.
        ValueError: If T, M, or herb data is negative or inconsistent.
    """
    # Basic type and value validation
    try:
        T = int(T)
        M = int(M)
    except (TypeError, ValueError):
        raise TypeError("T and M must be integers.")

    if T < 0:
        raise ValueError("T (time limit) must be non-negative.")
    if M < 0:
        raise ValueError("M (number of herbs) must be non-negative.")

    if not isinstance(herbs, list):
        raise TypeError("herbs must be a list.")

    if len(herbs) != M:
        raise ValueError("Length of herbs list does not match M.")

    # Validate each herb tuple
    processed_herbs = []
    for i, herb in enumerate(herbs):
        if not isinstance(herb, tuple) or len(herb) != 2:
            raise TypeError(f"Herb at index {i} is not a 2-element tuple.")
        time_req, value = herb
        if not isinstance(time_req, int) or not isinstance(value, int):
            raise TypeError(f"Herb at index {i} contains non-integer entries.")
        if time_req < 0:
            raise ValueError(f"Time requirement for herb at index {i} must be non-negative.")
        if value < 0:
            raise ValueError(f"Value for herb at index {i} must be non-negative.")
        processed_herbs.append((time_req, value))

    # Edge cases
    if T == 0 or M == 0:
        return 0

    # 1D DP array for 0/1 knapsack
    dp = [0] * (T + 1)

    for time_req, value in processed_herbs:
        if time_req > T:
            # Cannot pick this herb at all due to time constraint
            continue
        # Traverse backwards to ensure each herb is considered only once
        for t in range(T, time_req - 1, -1):
            new_value = dp[t - time_req] + value
            if new_value > dp[t]:
                dp[t] = new_value

    # The maximum value achievable within the time limit is the maximum over all capacities <= T
    return max(dp)

