        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if heights is None:
        return 0
    if not isinstance(heights, list):
        raise TypeError("heights must be a list of integers")
    if len(heights) == 0:
        return 0

    n = len(heights)
    # Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest Bitonic Subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1  # peak counted twice
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals
    return n - max_bitonic

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.

    Raises:
    ValueError: If the input is not a list of 3-element tuples.
    """
    try:
        if not isinstance(student_scores, list):
            raise TypeError("Input must be a list")
        for idx, s in enumerate(student_scores):
            if not isinstance(s, tuple) or len(s) != 3:
                raise ValueError(f"Element at index {idx} is not a valid tuple of (student_number, total_score, Chinese_score)")
        # Sort by total_score descending (-x[1]), Chinese_score descending (-x[2]), student_number ascending (x[0])
        return sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
    except Exception as e:
        raise ValueError(f"Invalid input: {e}") from e
